#!/usr/bin/env python3
"""Estimate PuddleDuck observation noise while the robot is stationary.

This is the PuddleDuck equivalent of the Unitree LowState observation-noise
script. It starts the firmware policy observation stream, records obs packets
without sending any actions, and reports centered noise statistics for:

  - gyro / base angular velocity
  - reported gravity, if firmware reports gravity
  - gravity reconstructed from quaternion
  - accelerometer, if firmware reports accelerometer
  - joint angles
  - joint velocities

The output includes both measured standard deviation and a uniform-noise
half-range equivalent. If a training pipeline injects uniform noise as
U(-scale, +scale), then scale ~= sqrt(3) * measured_std.
"""

from __future__ import annotations

import argparse
import csv
import datetime as _dt
import json
import math
import os
import pickle
import signal
import sys
import time
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Iterable

import numpy as np


DEFAULT_PORT = "/dev/puddleduck_ctrl"
DEFAULT_POLICY_NAME = "default"


def _is_finite_number(x: Any) -> bool:
    try:
        return math.isfinite(float(x))
    except Exception:
        return False


def _arr(values: Iterable[Any], *, dtype=np.float64) -> np.ndarray:
    return np.asarray(list(values), dtype=dtype).reshape(-1)


def quat_to_gravity_xyz(q_wxyz: Iterable[float]) -> np.ndarray:
    """Projected gravity in body frame from a wxyz quaternion.

    This matches the common policy convention: body-frame gravity unit vector,
    with world gravity [0, 0, -1].
    """
    q = _arr(q_wxyz, dtype=np.float64)
    if q.size != 4 or not np.all(np.isfinite(q)):
        return np.full(3, np.nan, dtype=np.float64)
    norm = float(np.linalg.norm(q))
    if norm <= 1e-12:
        return np.full(3, np.nan, dtype=np.float64)
    w, x, y, z = q / norm
    r = np.array(
        [
            [1.0 - 2.0 * (y * y + z * z), 2.0 * (x * y - z * w), 2.0 * (x * z + y * w)],
            [2.0 * (x * y + z * w), 1.0 - 2.0 * (x * x + z * z), 2.0 * (y * z - x * w)],
            [2.0 * (x * z - y * w), 2.0 * (y * z + x * w), 1.0 - 2.0 * (x * x + y * y)],
        ],
        dtype=np.float64,
    )
    g_world = np.array([0.0, 0.0, -1.0], dtype=np.float64)
    return r.T @ g_world


def _vector_or_none(*values: Any) -> np.ndarray | None:
    out = _arr(values, dtype=np.float64)
    if out.size == 0 or not np.all(np.isfinite(out)):
        return None
    return out


@dataclass
class Sample:
    wall_time_s: float
    num: int
    timestamp_us: int
    gyro: np.ndarray
    accel: np.ndarray | None
    gravity_reported: np.ndarray | None
    gravity_from_quat: np.ndarray | None
    quat_wxyz: np.ndarray | None
    joint_angles: np.ndarray
    joint_vel: np.ndarray


def sample_from_obs(msg: Any) -> Sample:
    quat = _vector_or_none(msg.quat_w, msg.quat_x, msg.quat_y, msg.quat_z)
    if quat is not None and np.linalg.norm(quat) < 1e-9:
        quat = None

    gravity_from_quat = quat_to_gravity_xyz(quat) if quat is not None else None
    if gravity_from_quat is not None and not np.all(np.isfinite(gravity_from_quat)):
        gravity_from_quat = None

    accel = _vector_or_none(msg.accel_x, msg.accel_y, msg.accel_z)
    gravity = _vector_or_none(msg.gravity_x, msg.gravity_y, msg.gravity_z)

    return Sample(
        wall_time_s=time.time(),
        num=int(getattr(msg, "num", 0)),
        timestamp_us=int(getattr(msg, "timestamp", 0)),
        gyro=_arr((msg.gyro_x, msg.gyro_y, msg.gyro_z), dtype=np.float64),
        accel=accel,
        gravity_reported=gravity,
        gravity_from_quat=gravity_from_quat,
        quat_wxyz=quat,
        joint_angles=_arr(getattr(msg, "joint_angles", []), dtype=np.float64),
        joint_vel=_arr(getattr(msg, "joint_vel", []), dtype=np.float64),
    )


def _stack(samples: list[Sample], attr: str) -> np.ndarray | None:
    rows = []
    for s in samples:
        val = getattr(s, attr)
        if val is None:
            continue
        arr = np.asarray(val, dtype=np.float64).reshape(-1)
        if arr.size == 0 or not np.all(np.isfinite(arr)):
            continue
        rows.append(arr)
    if not rows:
        return None
    width = max(r.size for r in rows)
    rows = [r for r in rows if r.size == width]
    if not rows:
        return None
    return np.vstack(rows)


def _axis_names(group: str, width: int, joint_names: list[str] | None = None) -> list[str]:
    if group in ("gyro", "accel", "gravity_reported", "gravity_from_quat") and width == 3:
        suffix = ["x", "y", "z"]
        return [f"{group}_{s}" for s in suffix]
    if group == "quat_wxyz" and width == 4:
        return ["quat_w", "quat_x", "quat_y", "quat_z"]
    if group in ("joint_angles", "joint_vel") and joint_names and len(joint_names) == width:
        prefix = "q" if group == "joint_angles" else "dq"
        return [f"{prefix}_{name}" for name in joint_names]
    return [f"{group}_{i}" for i in range(width)]


def _linear_drift_per_s(arr: np.ndarray, t: np.ndarray) -> np.ndarray:
    if arr.shape[0] < 3:
        return np.full(arr.shape[1], np.nan, dtype=np.float64)
    tt = np.asarray(t, dtype=np.float64)
    tt = tt - float(tt[0])
    denom = float(np.sum((tt - np.mean(tt)) ** 2))
    if denom <= 1e-12:
        return np.full(arr.shape[1], np.nan, dtype=np.float64)
    yy = arr - np.mean(arr, axis=0)
    return ((tt - np.mean(tt))[:, None] * yy).sum(axis=0) / denom


def summarize_array(arr: np.ndarray, *, t: np.ndarray | None = None) -> dict[str, Any]:
    arr = np.asarray(arr, dtype=np.float64)
    if arr.ndim != 2 or arr.shape[0] == 0:
        raise ValueError("summary expects a non-empty 2D array")
    mean = np.mean(arr, axis=0)
    centered = arr - mean
    std = np.std(centered, axis=0, ddof=0)
    median = np.median(arr, axis=0)
    mad_sigma = 1.4826 * np.median(np.abs(arr - median), axis=0)
    p2p = np.ptp(arr, axis=0)
    rms = np.sqrt(np.mean(arr * arr, axis=0))
    diff_std = np.std(np.diff(arr, axis=0), axis=0, ddof=0) if arr.shape[0] > 1 else np.full(arr.shape[1], np.nan)
    drift_per_s = _linear_drift_per_s(arr, t) if t is not None else np.full(arr.shape[1], np.nan)

    return {
        "n": int(arr.shape[0]),
        "width": int(arr.shape[1]),
        "mean": mean.tolist(),
        "std": std.tolist(),
        "mad_sigma": mad_sigma.tolist(),
        "min": np.min(arr, axis=0).tolist(),
        "max": np.max(arr, axis=0).tolist(),
        "peak_to_peak": p2p.tolist(),
        "rms": rms.tolist(),
        "first_difference_std": diff_std.tolist(),
        "drift_per_s": drift_per_s.tolist(),
        "scalar_mean_std": float(np.mean(std)),
        "scalar_rms_std": float(np.sqrt(np.mean(std * std))),
        "scalar_max_std": float(np.max(std)),
        "scalar_mean_mad_sigma": float(np.mean(mad_sigma)),
        "uniform_half_range_equiv_mean": float(np.sqrt(3.0) * np.mean(std)),
        "uniform_half_range_equiv_rms": float(np.sqrt(3.0) * np.sqrt(np.mean(std * std))),
        "scalar_mean_first_difference_std": float(np.nanmean(diff_std)),
        "scalar_mean_abs_drift_per_s": float(np.nanmean(np.abs(drift_per_s))),
    }


def write_raw_csv(path: Path, samples: list[Sample], joint_names: list[str] | None = None) -> None:
    if not samples:
        return
    max_joints = max((s.joint_angles.size for s in samples), default=0)
    if not joint_names or len(joint_names) != max_joints:
        joint_names = [str(i) for i in range(max_joints)]

    fields = ["sample_index", "wall_time_s", "obs_num", "timestamp_us"]
    fields += [f"gyro_{a}" for a in "xyz"]
    fields += [f"accel_{a}" for a in "xyz"]
    fields += [f"gravity_reported_{a}" for a in "xyz"]
    fields += [f"gravity_from_quat_{a}" for a in "xyz"]
    fields += ["quat_w", "quat_x", "quat_y", "quat_z"]
    fields += [f"q_{name}" for name in joint_names]
    fields += [f"dq_{name}" for name in joint_names]

    def vals3(v):
        if v is None:
            return [math.nan, math.nan, math.nan]
        vv = np.asarray(v, dtype=np.float64).reshape(-1)
        return [float(vv[i]) if i < vv.size else math.nan for i in range(3)]

    def vals4(v):
        if v is None:
            return [math.nan, math.nan, math.nan, math.nan]
        vv = np.asarray(v, dtype=np.float64).reshape(-1)
        return [float(vv[i]) if i < vv.size else math.nan for i in range(4)]

    with path.open("w", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=fields)
        writer.writeheader()
        for i, s in enumerate(samples):
            row = {
                "sample_index": i,
                "wall_time_s": f"{s.wall_time_s:.9f}",
                "obs_num": s.num,
                "timestamp_us": s.timestamp_us,
            }
            row.update(dict(zip([f"gyro_{a}" for a in "xyz"], vals3(s.gyro))))
            row.update(dict(zip([f"accel_{a}" for a in "xyz"], vals3(s.accel))))
            row.update(dict(zip([f"gravity_reported_{a}" for a in "xyz"], vals3(s.gravity_reported))))
            row.update(dict(zip([f"gravity_from_quat_{a}" for a in "xyz"], vals3(s.gravity_from_quat))))
            row.update(dict(zip(["quat_w", "quat_x", "quat_y", "quat_z"], vals4(s.quat_wxyz))))
            q = np.asarray(s.joint_angles, dtype=np.float64).reshape(-1)
            dq = np.asarray(s.joint_vel, dtype=np.float64).reshape(-1)
            for j, name in enumerate(joint_names):
                row[f"q_{name}"] = float(q[j]) if j < q.size else math.nan
                row[f"dq_{name}"] = float(dq[j]) if j < dq.size else math.nan
            writer.writerow(row)


def write_axis_summary_csv(path: Path, summaries: dict[str, dict[str, Any]], joint_names: list[str] | None = None) -> None:
    fields = [
        "group",
        "axis",
        "mean",
        "std",
        "mad_sigma",
        "min",
        "max",
        "peak_to_peak",
        "rms",
        "first_difference_std",
        "drift_per_s",
        "uniform_half_range_equiv",
    ]
    with path.open("w", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=fields)
        writer.writeheader()
        for group, st in summaries.items():
            width = int(st["width"])
            names = _axis_names(group, width, joint_names=joint_names)
            for i, axis in enumerate(names):
                writer.writerow(
                    {
                        "group": group,
                        "axis": axis,
                        "mean": st["mean"][i],
                        "std": st["std"][i],
                        "mad_sigma": st["mad_sigma"][i],
                        "min": st["min"][i],
                        "max": st["max"][i],
                        "peak_to_peak": st["peak_to_peak"][i],
                        "rms": st["rms"][i],
                        "first_difference_std": st["first_difference_std"][i],
                        "drift_per_s": st["drift_per_s"][i],
                        "uniform_half_range_equiv": math.sqrt(3.0) * float(st["std"][i]),
                    }
                )


def print_human_summary(summary: dict[str, Any], obs_mult: float) -> None:
    groups = summary["groups"]

    def scalar(group: str, key: str = "scalar_mean_std") -> float | None:
        if group not in groups:
            return None
        return float(groups[group][key]) * float(obs_mult)

    print("\n=== PUDDLEDUCK OBSERVATION NOISE ESTIMATE ===")
    print(f"samples:       {summary['n_samples']}")
    print(f"duration_s:    {summary['duration_wall_s']:.3f}")
    print(f"requested_hz:  {summary['requested_hz']:.3f}")
    print(f"actual_hz:     {summary['actual_hz_wall']:.3f} wall, {summary.get('actual_hz_firmware', float('nan')):.3f} firmware")
    print(f"imu_present:   accel={summary['imu_present']['accelerometer']} gravity={summary['imu_present']['gravity_reported']} quat={summary['imu_present']['quaternion']}")

    print("\n=== CENTERED STD SCALARS ===")
    for label, group in (
        ("gyro/base_ang_vel", "gyro"),
        ("gravity_reported", "gravity_reported"),
        ("gravity_from_quat", "gravity_from_quat"),
        ("accelerometer", "accel"),
        ("joint_pos", "joint_angles"),
        ("joint_vel", "joint_vel"),
    ):
        v = scalar(group)
        if v is not None:
            print(f"{label:22s}: {v:.8g}")

    print("\n=== UNIFORM HALF-RANGE EQUIVALENT ===")
    print("Use this if training noise is sampled as U(-scale, +scale).")
    for label, group in (
        ("base_ang_vel", "gyro"),
        ("gravity", "gravity_reported" if "gravity_reported" in groups else "gravity_from_quat"),
        ("accelerometer", "accel"),
        ("joint_pos", "joint_angles"),
        ("joint_vel", "joint_vel"),
    ):
        if group in groups:
            v = scalar(group, "uniform_half_range_equiv_mean")
            print(f"{label:22s}: {v:.8g}")

    # Keep the old Unitree script output shape too, because it is handy to paste.
    gravity_group = "gravity_reported" if "gravity_reported" in groups else "gravity_from_quat"
    print("\n=== SIMULATION READY VALUES: measured std ===")
    print("noise:")
    if scalar("gyro") is not None:
        print(f"  base_ang_vel: {scalar('gyro'):.8g}")
    if gravity_group in groups:
        print(f"  gravity: {scalar(gravity_group):.8g}")
    if scalar("accel") is not None:
        print(f"  accelerometer: {scalar('accel'):.8g}")
    if scalar("joint_angles") is not None:
        print(f"  joint_pos: {scalar('joint_angles'):.8g}")
    if scalar("joint_vel") is not None:
        print(f"  joint_vel: {scalar('joint_vel'):.8g}")

    print("\n# Legacy obs_noise dict shape")
    print("obs_noise_level = 1.0")
    print("obs_noise = {")
    if scalar("gyro") is not None:
        print(f'  "ang_vel": {scalar("gyro"):.8g},')
    if gravity_group in groups:
        print(f'  "gravity": {scalar(gravity_group):.8g},')
    if scalar("joint_angles") is not None:
        print(f'  "dof_pos": {scalar("joint_angles"):.8g},')
    if scalar("joint_vel") is not None:
        print(f'  "dof_vel": {scalar("joint_vel"):.8g},')
    print("}")


def load_joint_names(path: str | None, expected_n: int | None = None) -> list[str] | None:
    if not path:
        return None
    p = Path(path).expanduser()
    if not p.exists():
        raise FileNotFoundError(str(p))
    if p.suffix.lower() in (".json",):
        data = json.loads(p.read_text())
        for key in ("joints", "joint_names", "onnx_joints"):
            if isinstance(data, dict) and key in data:
                names = [str(x) for x in data[key]]
                return names
    # Plain text: one name per line or comma separated.
    text = p.read_text().strip()
    if not text:
        return None
    if "," in text:
        names = [x.strip() for x in text.split(",") if x.strip()]
    else:
        names = [x.strip() for x in text.splitlines() if x.strip() and not x.strip().startswith("#")]
    if expected_n is not None and len(names) != expected_n:
        print(f"[warn] joint name count {len(names)} != expected joint count {expected_n}; using numeric joint names", file=sys.stderr)
        return None
    return names


def collect(args: argparse.Namespace) -> list[Sample]:
    from pd.runtime import API  # imported lazily so --help works outside runtime env

    api = API(args.port)
    samples: list[Sample] = []
    stop_requested = False

    def _handle_signal(signum, frame):  # noqa: ARG001
        nonlocal stop_requested
        stop_requested = True
        print("\n[obs_noise] stop requested; finishing...", file=sys.stderr)

    old_sigint = signal.signal(signal.SIGINT, _handle_signal)
    old_sigterm = signal.signal(signal.SIGTERM, _handle_signal)

    try:
        if args.drain:
            api.drain_read_buffer()

        if not args.passive:
            dt = 1.0 / float(args.hz) if args.hz > 0 else 0.0
            print(f"[obs_noise] starting observation stream policy={args.policy_name!r} dt={dt:.6f}s", file=sys.stderr)
            api.policyStart(args.policy_name, dt=dt)
            if args.start_delay_s > 0:
                time.sleep(float(args.start_delay_s))

        print("[obs_noise] waiting for observations...", file=sys.stderr)
        start_wall = time.time()
        first_sample_wall = None
        last_progress = start_wall
        n_warmup = 0

        while not stop_requested:
            now = time.time()
            if now - start_wall > float(args.seconds) + float(args.warmup_s):
                break

            msg_type, msg = api.receive(blocking=True)
            if msg_type is None:
                continue
            if msg_type != "obs":
                if args.verbose:
                    print(f"[obs_noise] ignoring message type {msg_type!r}", file=sys.stderr)
                continue

            s = sample_from_obs(msg)
            if first_sample_wall is None:
                first_sample_wall = s.wall_time_s
            elapsed_from_first = s.wall_time_s - first_sample_wall
            if elapsed_from_first < float(args.warmup_s):
                n_warmup += 1
                continue
            samples.append(s)

            if args.progress and s.wall_time_s - last_progress >= 1.0:
                print(f"[obs_noise] collected {len(samples)} samples (+{n_warmup} warmup)", file=sys.stderr)
                last_progress = s.wall_time_s

            if args.max_samples is not None and len(samples) >= int(args.max_samples):
                break

        if not args.passive and not args.no_stop:
            try:
                api.policyStart("", dt=0.0)
            except Exception as exc:  # best effort during shutdown
                print(f"[warn] failed to stop observation stream: {exc}", file=sys.stderr)
    finally:
        signal.signal(signal.SIGINT, old_sigint)
        signal.signal(signal.SIGTERM, old_sigterm)

    return samples


def analyze(samples: list[Sample], args: argparse.Namespace) -> tuple[dict[str, Any], list[str] | None]:
    if not samples:
        raise RuntimeError("No observations collected")

    t_wall = np.asarray([s.wall_time_s for s in samples], dtype=np.float64)
    t_wall = t_wall - float(t_wall[0])
    ts_us = np.asarray([s.timestamp_us for s in samples], dtype=np.float64)
    ts_good = np.all(np.isfinite(ts_us)) and ts_us.size > 1 and np.ptp(ts_us) > 0
    t_fw = (ts_us - float(ts_us[0])) * 1e-6 if ts_good else t_wall

    max_joints = max((s.joint_angles.size for s in samples), default=0)
    joint_names = load_joint_names(args.joint_names, expected_n=max_joints) if args.joint_names else None

    summaries: dict[str, dict[str, Any]] = {}
    for group in ("gyro", "accel", "gravity_reported", "gravity_from_quat", "quat_wxyz", "joint_angles", "joint_vel"):
        arr = _stack(samples, group)
        if arr is None:
            continue
        summaries[group] = summarize_array(arr, t=t_fw)

    duration_wall = float(t_wall[-1] - t_wall[0]) if len(t_wall) > 1 else 0.0
    duration_fw = float(t_fw[-1] - t_fw[0]) if len(t_fw) > 1 else 0.0
    actual_hz_wall = float((len(samples) - 1) / duration_wall) if duration_wall > 1e-9 and len(samples) > 1 else 0.0
    actual_hz_fw = float((len(samples) - 1) / duration_fw) if duration_fw > 1e-9 and len(samples) > 1 else 0.0

    summary = {
        "created_at_utc": _dt.datetime.now(_dt.timezone.utc).isoformat(),
        "port": args.port,
        "policy_name": args.policy_name,
        "passive": bool(args.passive),
        "requested_hz": float(args.hz),
        "seconds_requested": float(args.seconds),
        "warmup_s": float(args.warmup_s),
        "obs_mult": float(args.obs_mult),
        "n_samples": int(len(samples)),
        "duration_wall_s": duration_wall,
        "duration_firmware_s": duration_fw,
        "actual_hz_wall": actual_hz_wall,
        "actual_hz_firmware": actual_hz_fw,
        "obs_num_first": int(samples[0].num),
        "obs_num_last": int(samples[-1].num),
        "timestamp_us_first": int(samples[0].timestamp_us),
        "timestamp_us_last": int(samples[-1].timestamp_us),
        "imu_present": {
            "accelerometer": "accel" in summaries,
            "gravity_reported": "gravity_reported" in summaries,
            "gravity_from_quat": "gravity_from_quat" in summaries,
            "quaternion": "quat_wxyz" in summaries,
        },
        "joint_count": int(max_joints),
        "joint_names": joint_names,
        "groups": summaries,
        "training_noise_values_measured_std": {},
        "training_noise_values_uniform_half_range_equiv": {},
    }

    # Suggested keys matching the current Darkwing/Open_BDX naming.
    gravity_group = "gravity_reported" if "gravity_reported" in summaries else ("gravity_from_quat" if "gravity_from_quat" in summaries else None)
    mapping = {
        "base_ang_vel": "gyro",
        "accelerometer": "accel",
        "joint_pos": "joint_angles",
        "joint_vel": "joint_vel",
    }
    if gravity_group:
        mapping["gravity"] = gravity_group
    for out_key, group in mapping.items():
        if group not in summaries:
            continue
        summary["training_noise_values_measured_std"][out_key] = float(args.obs_mult) * float(summaries[group]["scalar_mean_std"])
        summary["training_noise_values_uniform_half_range_equiv"][out_key] = float(args.obs_mult) * float(summaries[group]["uniform_half_range_equiv_mean"])

    return summary, joint_names


def main() -> None:
    p = argparse.ArgumentParser(
        description="Estimate PuddleDuck observation noise from idle/cradled robot observations.",
        formatter_class=argparse.ArgumentDefaultsHelpFormatter,
    )
    p.add_argument("--port", default=os.environ.get("PUDDLEDUCK_PORT", DEFAULT_PORT), help="PuddleDuck serial control port")
    p.add_argument("--policy-name", default=DEFAULT_POLICY_NAME, help="Firmware policy name to start for observation streaming")
    p.add_argument("--hz", type=float, default=200.0, help="Requested observation stream Hz via policyStart dt")
    p.add_argument("--seconds", type=float, default=20.0, help="Seconds of post-warmup samples to collect")
    p.add_argument("--warmup-s", type=float, default=1.0, help="Discard this many initial seconds after first obs")
    p.add_argument("--start-delay-s", type=float, default=0.1, help="Delay after policyStart before recording/waiting")
    p.add_argument("--obs-mult", type=float, default=1.0, help="Multiplier applied to printed simulation-ready values")
    p.add_argument("--max-samples", type=int, default=None, help="Stop after this many post-warmup samples")
    p.add_argument("--out", default=None, help="Output prefix or directory. Default: obs_noise_YYYYmmdd_HHMMSS")
    p.add_argument("--joint-names", default=None, help="Optional text/JSON joint names for CSV axis labels")
    p.add_argument("--passive", action="store_true", help="Do not call policyStart; only listen to an already-running stream")
    p.add_argument("--no-stop", action="store_true", help="Do not send policyStart('', dt=0) on exit")
    p.add_argument("--no-drain", dest="drain", action="store_false", help="Do not clear the serial receive buffer before collecting")
    p.add_argument("--no-progress", dest="progress", action="store_false", help="Disable per-second progress messages")
    p.add_argument("--verbose", action="store_true", help="Verbose ignored-message logging")
    p.set_defaults(drain=True, progress=True)
    args = p.parse_args()

    samples = collect(args)
    if len(samples) < 2:
        raise SystemExit(f"Need at least 2 samples; got {len(samples)}")

    summary, joint_names = analyze(samples, args)

    out_arg = args.out
    if out_arg is None:
        out_base = Path(f"obs_noise_{_dt.datetime.now().strftime('%Y%m%d_%H%M%S')}")
    else:
        out_base = Path(out_arg).expanduser()

    if out_base.suffix:
        out_dir = out_base.parent
        prefix = out_base.stem
    else:
        out_dir = out_base
        prefix = "obs_noise"
    out_dir.mkdir(parents=True, exist_ok=True)

    json_path = out_dir / f"{prefix}_summary.json"
    csv_path = out_dir / f"{prefix}_samples.csv"
    axis_path = out_dir / f"{prefix}_axis_summary.csv"
    pkl_path = out_dir / f"{prefix}_samples.pkl"

    json_path.write_text(json.dumps(summary, indent=2, sort_keys=True), encoding="utf-8")
    write_raw_csv(csv_path, samples, joint_names=joint_names)
    write_axis_summary_csv(axis_path, summary["groups"], joint_names=joint_names)
    with pkl_path.open("wb") as f:
        pickle.dump([s.__dict__ for s in samples], f)

    print_human_summary(summary, float(args.obs_mult))
    print("\n=== WRITTEN FILES ===")
    print(json_path)
    print(axis_path)
    print(csv_path)
    print(pkl_path)


if __name__ == "__main__":
    main()
